/* Signature Belarusian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ivanmir": "From Ivan + mir (peace).", "Marynaslava": "From Maryna + slava (glory).", "Aleksandrmil": "From Aleksandr + mil (dear).", "Olgamir": "From Olga + mir.", "Dmitrislav": "From Dmitri + slav.", "Natalyamila": "From Natalya + mila (dear).", "Ivanmirovich": "Signature patronymic-style surname.", "Marynaslavna": "Signature feminine patronymic-style surname.", "Aleksandrmilov": "Signature surname in -ov style.", "Olgamirski": "Signature surname in -ski style."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ivanmir';
console.log(lookup(q));

